-- A person's snapshot lines: each change of the sheet's today records, for each person, the day being left and
-- their due-total on it ('n/a' when their grade had no rate then), as the SNAPSHOT audit line has it.
CREATE TABLE person_snapshot (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    left_on   DATE         NOT NULL,
    due_total VARCHAR(20)  NOT NULL
);
CREATE INDEX person_snapshot_person ON person_snapshot (sheet_id, person_id, left_on, id);
-- A snapshot line keeps the today the sheet moved to when it was written: as of a date before that, the day it was
-- written for had not been left yet. A line kept before has none (it shows as of any date after its day).
ALTER TABLE person_snapshot ADD COLUMN written_on DATE;
-- A sheet's history: after each change, what the sheet held (its dated settings, rates, people and claims, as JSON)
-- is kept under the sheet's today then; the latest kept under a day on or before a date is the sheet as it stood
-- at the end of that date, as a statement taken as of that date reads it.
CREATE TABLE sheet_snapshot (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    as_of    DATE         NOT NULL,
    state    CLOB         NOT NULL
);
CREATE INDEX sheet_snapshot_as_of ON sheet_snapshot (sheet_id, as_of, id);
